import{_ as e,o as i,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"2019-12-19 -- Ceph Performance Meeting","description":"","frontmatter":{"title":"2019-12-19 -- Ceph Performance Meeting","date":"2019-12-19T00:00:00.000Z","updated":"2019-12-19T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","CRUSH 算法","高可用性","可伸缩性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-12-19_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2019/2019-12-19_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780459816000}'),r={name:"posts/2019/2019-12-19_-_-_Ceph_Performance_Meeting.md"};function o(n,l,s,P,u,p){return i(),a("div",null,[...l[0]||(l[0]=[t('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><p>在2019年12月19日的Ceph性能会议上，与会者讨论了多个关键议题，包括PR（Pull Requests，即代码提交请求）的更新、硬件推荐文档的修改、性能优化等多个方面。</p><h3 id="主要议题与讨论内容" tabindex="-1">主要议题与讨论内容 <a class="header-anchor" href="#主要议题与讨论内容" aria-label="Permalink to &quot;主要议题与讨论内容&quot;">​</a></h3><ol><li><p><strong>新PR介绍</strong>：</p><ul><li>来自Xixing（Shai Shin Guo 或 Guo）的PR，主要改进了管理器中的并行计算和平衡器，旨在消除upmap模式下对ms基础设施的使用。</li><li>讨论了两个被stale bot关闭的PR： <ul><li>避免双重缓存的PR，等待Adam的数据库分片PR合并后再进行重写。</li><li>增加messenger IOPS的PR，由Roman在SUSE编写，Greg曾审阅但未有进展，建议作者重新开启或提交新PR。</li></ul></li></ul></li><li><p><strong>硬件推荐文档更新</strong>：</p><ul><li>更新了硬件推荐文档的内容，但尚未获得批准。</li></ul></li><li><p><strong>RGW桶分片默认数量调整</strong>：</p><ul><li>讨论了增加RGW桶分片默认数量的PR，进行了测试，但发现性能反而下降，需要进一步分析原因。</li></ul></li><li><p><strong>Purple测试适配ARM架构</strong>：</p><ul><li>一个旧PR，关于将Purple测试适配到ARM架构，最近由Kifu审阅并更新。</li></ul></li><li><p><strong>避免OSD和RGW之间的解码-重新编码步骤</strong>：</p><ul><li>讨论了避免OSD和RGW之间解码-重新编码步骤的PR，提出了在CLS侧添加模板的可能解决方案。</li></ul></li><li><p><strong>PG日志性能优化</strong>：</p><ul><li>继续进行PG日志的测试，发现性能提升在达到一定上限后转为降低CPU使用率，考虑采用新的存储机制如循环缓冲区。</li></ul></li></ol><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>等待Adam的数据库分片PR合并后再重写避免双重缓存的PR。</li><li>建议增加messenger IOPS的PR作者重新开启或提交新PR。</li><li>硬件推荐文档更新的PR需要获得批准。</li><li>增加RGW桶分片默认数量的PR需要进一步测试和分析性能问题。</li><li>避免OSD和RGW之间解码-重新编码步骤的PR需要进一步讨论和实现。</li><li>PG日志性能优化需要探索新的存储机制。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>重写避免双重缓存的PR。</li><li>重新开启或提交增加messenger IOPS的PR。</li><li>获取硬件推荐文档更新的PR批准。</li><li>进一步测试和分析增加RGW桶分片默认数量的PR。</li><li>实现避免OSD和RGW之间解码-重新编码步骤的PR。</li><li>探索PG日志的新存储机制。</li></ul><h3 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h3><ul><li>会议结束时，提醒与会者享受假期，并将在一月份重新开会。</li></ul><h3 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h3><ul><li>会议在简短的讨论后结束，祝大家节日快乐。</li></ul>',12)])])}const d=e(r,[["render",o]]);export{_ as __pageData,d as default};
